import{_ as i,a as l,c as t,ac as a}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"English 时态","description":"常用时态的动词构成与中英例句","frontmatter":{"title":"English 时态","description":"常用时态的动词构成与中英例句","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/English/2023-05-17-6-tense.md","date":"Sat May 16 2020 12:12:59 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"英语基础","summary":"常用时态的动词构成与中英例句","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"英语句子结构与句型练习","link":"/life/english/foundations/5-sentence_structure"},"next":{"text":"英语主动与被动语态","link":"/life/english/foundations/7-voice"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"英语句子结构与句型练习","link":"/life/english/foundations/5-sentence_structure"},"next":{"text":"英语主动与被动语态","link":"/life/english/foundations/7-voice"}},"headers":[],"relativePath":"life/english/foundations/6-tense.md","filePath":"life/english/foundations/6-tense.md"}'),n={name:"life/english/foundations/6-tense.md"};function o(r,e,s,h,u,c){return l(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="english-时态" tabindex="-1">English 时态 <a class="header-anchor" href="#english-时态" aria-label="Permalink to &quot;English 时态&quot;">​</a></h1><p>这里选取八种常见时间表达，按动词形式和所处时间理解；不是英语全部时态与体的完整目录。先判断事件与“现在”或某个过去时间点的关系，再选择形式。</p><h2 id="时态" tabindex="-1">时态 <a class="header-anchor" href="#时态" aria-label="Permalink to &quot;时态&quot;">​</a></h2><ol><li><p>一般现在时（Present Simple）</p><blockquote><p>用于表示习惯、经常发生的动作或一般事实。动词通常用原形，第三人称单数需作相应变化。例如：</p></blockquote><ul><li>I write an email to my boss every day.（我每天给我的老板写邮件）</li><li>She always drinks coffee in the morning.（她每天早上喝咖啡）</li><li>The sun rises in the east and sets in the west.（太阳从东方升起，从西方落下）</li></ul></li><li><p>一般过去时（Past Simple）</p><blockquote><p>用于表示过去发生的动作或状态，使用动词过去式。例如：</p></blockquote><ul><li>We went to the beach last weekend.（我们上周末去了海滩）</li><li>He studied English for three hours yesterday.（他昨天学习英语三个小时）</li><li>They played soccer every afternoon when they were kids.（他们小时候每天下午都踢足球）</li></ul></li><li><p>将来时（Future Simple）</p><blockquote><p>用于表示将要发生的动作或状态通常使用助动词“will”加上动词的原形构成例如：</p></blockquote><ul><li>He will meet his friend at the airport tomorrow.（他明天会在机场见他的朋友）</li><li>I will cook dinner for my family tonight.（今晚我会为我的家人做饭）</li><li>They will take a vacation next month.（他们下个月会去度假）</li></ul></li><li><p>现在进行时（Present Continuous）</p><blockquote><p>用于表示当前正在进行的动作或状态通常使用助动词“be”加上动词的现在分词构成例如：</p></blockquote><ul><li>She is reading a book right now.（她现在正在看书）</li><li>They are having a meeting in the conference room.（他们正在会议室开会）</li><li>I am learning to play guitar.（我正在学习弹吉他）</li></ul></li><li><p>过去进行时（Past Continuous）</p><blockquote><p>用于表示过去某个时间正在发生的动作通常使用助动词“was/were”加上动词的现在分词构成例如：</p></blockquote><ul><li>He was watching TV when she arrived.（她到达时他正在看电视）</li><li>I was walking in the park when it started raining.（下雨时我正在公园里散步）</li><li>They were studying for their exams all night.（他们整晚都在备考）</li></ul></li><li><p>将来进行时（Future Continuous）</p><blockquote><p>用于表示将来某个时间正在进行的动作通常使用助动词“will be”加上动词的现在分词构成例如：</p></blockquote><ul><li>I will be traveling to Europe this summer.（今年夏天我会去欧洲旅行）</li><li>They will be working on the project all day tomorrow.（明天一整天他们都会在工作这个项目）</li><li>We will be waiting for you at the airport.（我们会在机场等你）</li></ul></li><li><p>现在完成时（Present Perfect）</p><blockquote><p>形式是 have/has + 过去分词，核心是过去与现在的联系。常见用途有：持续到现在的状态、截至现在的经历或次数、过去动作带来的当前结果。并非所有例子都表示某个动作一直持续。</p></blockquote><ul><li>They have lived in this city for ten years.（他们已在此居住十年，当前仍居住在这里）：持续状态，for 后接时段。</li><li>She has watched that movie three times.（截至现在，她看过那部电影三遍）：经历次数，不表示一直在看。</li><li>I have studied English since I was a child.（我从小学习英语至今）：since 后给出起点。</li><li>I have lost my key.（我把钥匙弄丢了）：强调现在没有钥匙这一结果。</li></ul><p>对照 She watched that movie three times last year：last year 是已结束的过去时段，用一般过去时。现在完成时通常不与 yesterday、last year 这类已结束的具体过去时间直接搭配。</p></li><li><p>过去完成进行时（Past Perfect Continuous）</p><blockquote><p>用于表示过去某个时间之前一直在进行的动作通常使用助动词“had been”加上动词的现在分词构成例如：</p></blockquote><ul><li>He had been working on the project for two weeks before he realized he had made a mistake.（他在意识到自己犯了一个错误之前已经连续工作了两周）</li><li>We had been waiting for the bus for an hour when it finally arrived.（公交车终于到站时，我们已经等了一个小时了）</li><li>They had been studying English every day for a year before they took the TOEFL exam.（在参加托福考试之前，他们已经连续一年每天都在学习英语）</li></ul></li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://learnenglish.britishcouncil.org/free-resources/grammar/b1-b2/present-perfect" target="_blank" rel="noopener noreferrer">British Council：现在完成时的持续、经历和当前结果</a></li></ul>',6)])])}const g=i(n,[["render",o]]);export{p as __pageData,g as default};
